BEGIN;
CREATE OR REPLACE FUNCTION encova_finance_holding_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'FINANCE_HISTORY_IMMUTABLE' USING ERRCODE='P0001';END IF;
 IF TG_OP='UPDATE' THEN
  IF ROW(NEW.id,NEW.number,NEW."createdById",NEW."createdAt") IS DISTINCT FROM ROW(OLD.id,OLD.number,OLD."createdById",OLD."createdAt") OR(NEW.version<>OLD.version+1 AND(to_jsonb(NEW)-ARRAY['usedAt','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['usedAt','updatedAt'])) THEN RAISE EXCEPTION 'FINANCE_STALE_VERSION' USING ERRCODE='P0001';END IF;
  IF OLD."usedAt" IS NOT NULL AND(to_jsonb(NEW)-ARRAY['name','active','version','updatedAt']) IS DISTINCT FROM(to_jsonb(OLD)-ARRAY['name','active','version','updatedAt']) THEN RAISE EXCEPTION 'FINANCE_HOLDING_TERMS_USED' USING ERRCODE='P0001';END IF;
  IF NEW."usedAt" IS DISTINCT FROM OLD."usedAt" AND(OLD."usedAt" IS NOT NULL OR(NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "holdingId"=NEW.id) AND NOT EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId"=NEW.id) AND NOT EXISTS(SELECT 1 FROM public."FinanceJournalEntry" e JOIN public."FinanceMovement" m ON m.id=e."movementId" WHERE m."holdingId"=NEW.id))) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 END IF;
 IF NOT NEW.active AND EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId"=NEW.id HAVING coalesce(sum(amount),0)<>0) THEN RAISE EXCEPTION 'FINANCE_HOLDING_OUTSTANDING' USING ERRCODE='P0001';END IF;
 IF NOT NEW.active AND EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "holdingId"=NEW.id HAVING coalesce(sum("costDelta"),0)<>0 OR coalesce(sum("carryingDelta"),0)<>0 OR coalesce(sum("unitsDelta"),0)<>0) THEN RAISE EXCEPTION 'FINANCE_HOLDING_OUTSTANDING' USING ERRCODE='P0001';END IF;
 IF TG_OP='INSERT' OR OLD."usedAt" IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public."FinanceParty" WHERE id=NEW."partyId" AND active) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."investmentAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='INVESTMENT' AND "reportGroup"=CASE WHEN NEW.classification='CURRENT' THEN 'CURRENT_ASSETS' ELSE 'NONCURRENT_ASSETS' END) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_MAPPING' USING ERRCODE='P0001';END IF;
  IF NEW."policyStatus"='REVIEWED' AND(NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."gainAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."lossAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."feeAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type IN('DIRECT_COST','OPERATING_EXPENSE','OTHER_EXPENSE')) OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."incomeAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_INCOME') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."incomeControlAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='INVESTMENT_INCOME_RECEIVABLE') OR NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."impairmentAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type='OTHER_EXPENSE') OR(NEW."measurementMode"='MANUAL_VALUATION' AND NOT EXISTS(SELECT 1 FROM public."FinanceAccount" WHERE id=NEW."valuationOffsetAccountId" AND active AND "isPosting" AND NOT "isContra" AND "controlType"='NONE' AND type=CASE WHEN NEW."valuationTreatment"='EQUITY' THEN 'EQUITY' ELSE 'OTHER_INCOME' END))) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_POLICY' USING ERRCODE='P0001';END IF;
 END IF;RETURN NEW;END $$;
CREATE OR REPLACE FUNCTION encova_finance_movement_effects(actor UUID,target UUID,entry_id UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ BEGIN
 INSERT INTO public."FinanceInvestmentIncomeEvent"(id,"holdingId","movementId","journalId","effectiveDate",amount) SELECT gen_random_uuid(),v."holdingId",target,entry_id,d."postingDate",v.amount FROM public.encova_finance_investment_income_expected(target)v JOIN public."FinanceMovement" d ON d.id=target;
 UPDATE public."FinanceInvestmentHolding" SET "usedAt"=coalesce("usedAt",CURRENT_TIMESTAMP) WHERE id=(SELECT "holdingId" FROM public."FinanceMovement" WHERE id=target);
 PERFORM public.encova_finance_movement_effects_f23(actor,target,entry_id);
END $$;
CREATE OR REPLACE FUNCTION encova_finance_check_movement(target UUID) RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$ DECLARE d public."FinanceMovement"%ROWTYPE;j UUID;a public."FinanceInvestmentAllocation"%ROWTYPE;BEGIN
 IF target IS NULL THEN RETURN;END IF;PERFORM public.encova_finance_check_movement_f23(target);SELECT * INTO d FROM public."FinanceMovement" WHERE id=target;SELECT id INTO j FROM public."FinanceJournalEntry" WHERE "movementId"=target;
 IF(d.kind IN('INVESTMENT_DISPOSAL','INVESTMENT_IMPAIRMENT','INVESTMENT_VALUATION_UP','INVESTMENT_VALUATION_DOWN'))<>(EXISTS(SELECT 1 FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target)) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 FOR a IN SELECT * FROM public."FinanceInvestmentAllocation" WHERE "movementId"=target LOOP PERFORM public.encova_finance_investment_check_allocation(a.id);END LOOP;
 IF d.state<>'POSTED' THEN IF EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;RETURN;END IF;
 IF EXISTS(SELECT 1 FROM public."FinanceInvestmentEvent" WHERE "movementId"=target AND("journalId" IS DISTINCT FROM j OR("journalId" IS NULL AND NOT public.encova_finance_investment_register_only(target)))) OR EXISTS((SELECT "holdingId",amount FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target) EXCEPT(SELECT * FROM public.encova_finance_investment_income_expected(target))) OR EXISTS((SELECT * FROM public.encova_finance_investment_income_expected(target)) EXCEPT(SELECT "holdingId",amount FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target)) OR EXISTS(SELECT 1 FROM public."FinanceInvestmentIncomeEvent" WHERE "movementId"=target AND("journalId" IS DISTINCT FROM j OR "effectiveDate"<>d."postingDate")) THEN RAISE EXCEPTION 'FINANCE_SOURCE_MISMATCH' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT sum(amount) OVER(PARTITION BY "holdingId" ORDER BY "effectiveDate" RANGE UNBOUNDED PRECEDING) balance FROM public."FinanceInvestmentIncomeEvent" WHERE "holdingId" IN(SELECT "holdingId" FROM public.encova_finance_investment_income_expected(target)))v WHERE balance<0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_INCOME_CAPACITY' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT l.cost AS original_cost,l.units AS original_units,sum(e."costDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) cost,sum(e."unitsDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) units FROM public."FinanceInvestmentEvent" e JOIN public."FinanceInvestmentLot" l ON l.id=e."lotId" WHERE e."lotId" IN(SELECT "lotId" FROM public.encova_finance_investment_expected(target)))v WHERE cost>original_cost OR units>original_units) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
 IF EXISTS(SELECT 1 FROM(SELECT sum(e."costDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) cost,sum(e."carryingDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) carrying,sum(e."unitsDelta") OVER(PARTITION BY e."lotId" ORDER BY e."effectiveDate" RANGE UNBOUNDED PRECEDING) units FROM public."FinanceInvestmentEvent" e WHERE e."lotId" IN(SELECT "lotId" FROM public.encova_finance_investment_expected(target)))v WHERE cost=0 AND coalesce(units,0)=0 AND carrying<>0) THEN RAISE EXCEPTION 'FINANCE_INVESTMENT_CAPACITY' USING ERRCODE='P0001';END IF;
END $$;
COMMIT;
